//! Native Swift SDK generation for Kaji.
//!
//! The generated package deliberately uses Foundation's `URLSession` and
//! `Codable` rather than a third-party HTTP or JSON runtime. It consequently
//! works in server-side Swift as well as Apple application targets without
//! making an SDK consumer adopt a dependency graph chosen by the generator.

mod webhooks;
pub use webhooks::{Webhooks, webhooks};
mod bundled;
mod cursor_pagination;
mod package;
mod pagination;
pub use package::{PackageExt, Settings, Swift, package, sdk};

use std::collections::BTreeMap;
use std::fmt::Write;

use anyhow::{Result, bail};
use kaji_core::{
    AdditionalProperties, Api, Field, GeneratedFile, GeneratedTree, Operation, Schema, SchemaKind,
    SchemaValue, SdkClientStyle,
};
use serde_json::Value;

const NOTICE: &str = "// Generated by Kaji. Do not edit.\n";

/// Generates a self-contained Swift Package Manager SDK below `output_dir`.
pub(crate) fn render_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    style: SdkClientStyle,
) -> Result<GeneratedTree> {
    for schema in &api.schemas {
        if let SchemaKind::Object { fields, .. } = &schema.value.kind {
            let mut names = std::collections::BTreeMap::new();
            for field in fields {
                let native = identifier(&field.name);
                if let Some(previous) = names.insert(native.clone(), &field.name) {
                    anyhow::bail!(
                        "swift model '{}' properties '{}' and '{}' collide as native identifier '{}'",
                        schema.name,
                        previous,
                        field.name,
                        native
                    );
                }
            }
        }
    }

    for operation in &api.operations {
        if operation.request_body.as_ref().is_some_and(|body| {
            body.media_types.iter().any(|media| {
                media
                    .content_type
                    .to_ascii_lowercase()
                    .starts_with("multipart/")
            })
        }) {
            bail!(
                "Swift operation '{}' requires multipart encoding, which the native Swift SDK does not yet support",
                operation.id
            );
        }
        if operation
            .responses
            .iter()
            .flat_map(|response| &response.media_types)
            .any(|media| {
                media
                    .content_type
                    .split(';')
                    .next()
                    .is_some_and(|value| value.trim().eq_ignore_ascii_case("text/event-stream"))
            })
        {
            bail!(
                "Swift operation '{}' requires SSE streaming, which the native Swift SDK does not yet support",
                operation.id
            );
        }
    }
    let root = normalized_root(output_dir)?;
    let package = package_name
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("{}-sdk", kebab_case(&api.name)));
    let module = type_name(&package);
    let pagination = pagination::render(api)?;
    let mut tree = GeneratedTree::default();
    insert(
        &mut tree,
        &root,
        "Package.swift",
        package_manifest(&package, &module),
    )?;
    insert(
        &mut tree,
        &root,
        "README.md",
        readme(api, &package, &module, style)
            + if pagination.is_empty() {
                ""
            } else {
                "\n## Pagination\n\nDeclared string-cursor operations also expose `<operation>Pages(...)`. Their lazy `KajiCursorSequence` preserves the initial caller cursor, yields full responses, stops on missing/null/empty or repeated continuation tokens, and checks cancellation before each request. String query/header/path controls are supported; body and integer cursors fail generation.\n\nDeclared page-number operations expose `<operation>Pages(...)`, an `AsyncSequence` of full decoded pages. Iterate with `for try await page in client.<operation>Pages(...)`. Requests run only when the iterator advances and retain the ordinary operation transport, middleware, headers, and body. Optional page defaults to 1; explicit 0 is preserved. Required page remains a required argument. A positive declared limit stops after a short page; an empty page always stops and is yielded once. Invalid controls, malformed results selectors, integer overflow, and 10,000 pages terminate with `KajiPaginationError`. Cancellation is checked before each request. Page/limit must be nonnullable scalar integer parameter controls; body-bound controls are rejected during generation.\n"
            },
    )?;
    insert(
        &mut tree,
        &root,
        "STYLE_GUIDE.md",
        style_guide(api, &module, style),
    )?;
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/JSONValue.swift"),
        json_value(),
    )?;
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/KajiClient.swift"),
        client_runtime(),
    )?;
    for schema in &api.schemas {
        insert(
            &mut tree,
            &root,
            &format!("Sources/{module}/Models/{}.swift", type_name(&schema.name)),
            render_model_for_api(api, schema),
        )?;
    }
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/Operations.swift"),
        render_operations(api).replace("\n}\n", &format!("\n{pagination}\n}}\n")),
    )?;
    if !pagination.is_empty() {
        insert(
            &mut tree,
            &root,
            &format!("Sources/{module}/Pagination.swift"),
            include_str!("page_runtime.swift.txt").into(),
        )?;
    }
    if style == SdkClientStyle::Namespaced {
        for (resource, operations) in operation_groups(api) {
            insert(
                &mut tree,
                &root,
                &format!("Sources/{module}/Resources/{resource}Resource.swift"),
                render_resource(api, &resource, &operations),
            )?;
        }
    }
    Ok(tree)
}

fn normalized_root(output_dir: &str) -> Result<String> {
    let root = output_dir.trim_matches('/');
    if root.is_empty() {
        bail!("Swift SDK output directory cannot be empty");
    }
    if root.split('/').any(|part| part == "..") {
        bail!("Swift SDK output directory cannot contain parent-directory components");
    }
    Ok(root.to_owned())
}

fn insert(tree: &mut GeneratedTree, root: &str, path: &str, contents: String) -> Result<()> {
    tree.insert(GeneratedFile::new(format!("{root}/{path}"), contents)?)
}

fn package_manifest(package: &str, module: &str) -> String {
    format!(
        "// swift-tools-version: 5.9\nimport PackageDescription\n\nlet package = Package(\n    name: {package:?},\n    platforms: [.macOS(.v13), .iOS(.v16)],\n    products: [.library(name: {module:?}, targets: [{module:?}])],\n    targets: [.target(name: {module:?})]\n)\n"
    )
}

fn readme(api: &Api, package: &str, module: &str, style: SdkClientStyle) -> String {
    let call = api.operations.first().map_or_else(
        || "// Call an operation on client.".to_owned(),
        |operation| {
            format!(
                "let response = try await client.{}()",
                function_name(&operation.id)
            )
        },
    );
    let style_note = match style {
        SdkClientStyle::Flat => "Operations are available directly on `KajiClient`.",
        SdkClientStyle::Namespaced => {
            "Operations are available directly on `KajiClient`; resource facades are also generated for navigation."
        }
    };
    let mut output = format!(
        "# {package}\n\nGenerated Swift SDK for {}. {style_note}\n\n```swift\nimport {module}\n\nlet client = KajiClient(options: .init(baseURL: URL(string: \"https://api.example.com\")!))\n{call}\n```\n\nUse Swift Package Manager to add this directory as a local package or publish it to a source-control repository.\n",
        api.name
    );
    output.push_str(&r#"
## Customer middleware

```swift
import Foundation
import MODULE
let transport = KajiMiddlewareTransport(inner: KajiURLSessionTransport()) { request, next in
    var request = request
    request.setValue("example", forHTTPHeaderField: "X-Customer")
    do {
        let (data, response) = try await next(request)
        // Inspect or replace data/response before normal SDK decoding.
        return (data, response)
    } catch {
        // Inspect, recover with a synthetic response, or propagate.
        throw error
    }
}
let client = KajiClient(options: .init(baseURL: URL(string: "https://api.example.com")!), transport: transport)
```

Nest wrappers for composition; outer layers see requests first and responses last. Implement `KajiTransport` directly to substitute execution, or return a response without calling `next`. Existing `session:` initialization remains supported. Middleware wraps the buffered transport; it does not add streaming or automatic retries. Errors from HTTP status validation and decoding occur after middleware. Captures must satisfy Swift `Sendable` rules. Lifecycle hooks remain separate notifications.
"#.replace("MODULE", module));
    output
}

fn style_guide(api: &Api, module: &str, style: SdkClientStyle) -> String {
    let surface = match style {
        SdkClientStyle::Flat => "Operations are direct async methods on `KajiClient`.",
        SdkClientStyle::Namespaced => {
            "Operations remain direct async methods on `KajiClient`; named resource facades delegate to those methods without duplicating HTTP behavior."
        }
    };
    format!(
        "# {} Swift SDK style guide\n\nModule: `{module}`.\n\n{surface}\n\n## Errors\n\nUnsuccessful HTTP responses throw `KajiAPIError.status`. Transport and decoding errors are surfaced unchanged so callers can use normal Swift error handling.\n\n## Authentication and hooks\n\nSet API credentials or defaults through `KajiClientOptions.headers`. `KajiClientHook` provides request and response callbacks for telemetry, tracing, or policy.\n\n## Concurrency\n\nClients, models, and JSON values are `Sendable` where Swift's standard library permits it. Every generated operation is `async`.\n",
        api.name
    )
}

fn json_value() -> String {
    format!(
        "{NOTICE}\nimport Foundation\n\n/// A JSON value used for unconstrained OpenAPI schemas.\npublic enum JSONValue: Codable, Sendable, Equatable {{\n    case null\n    case bool(Bool)\n    case integer(Int64)\n    case unsignedInteger(UInt64)\n    case number(Double)\n    case string(String)\n    case array([JSONValue])\n    case object([String: JSONValue])\n\n    public init(from decoder: Decoder) throws {{\n        let container = try decoder.singleValueContainer()\n        if container.decodeNil() {{ self = .null }}\n        else if let value = try? container.decode(Bool.self) {{ self = .bool(value) }}\n        else if let value = try? container.decode(Int64.self) {{ self = .integer(value) }}\n        else if let value = try? container.decode(UInt64.self) {{ self = .unsignedInteger(value) }}\n        else if let value = try? container.decode(Double.self) {{ self = .number(value) }}\n        else if let value = try? container.decode(String.self) {{ self = .string(value) }}\n        else if let value = try? container.decode([JSONValue].self) {{ self = .array(value) }}\n        else {{ self = .object(try container.decode([String: JSONValue].self)) }}\n    }}\n\n    public func encode(to encoder: Encoder) throws {{\n        var container = encoder.singleValueContainer()\n        switch self {{\n        case .null: try container.encodeNil()\n        case .bool(let value): try container.encode(value)\n        case .integer(let value): try container.encode(value)\n        case .unsignedInteger(let value): try container.encode(value)\n        case .number(let value): try container.encode(value)\n        case .string(let value): try container.encode(value)\n        case .array(let value): try container.encode(value)\n        case .object(let value): try container.encode(value)\n        }}\n    }}\n}}\n\ninternal struct KajiCodingKey: CodingKey {{\n    let stringValue: String\n    let intValue: Int? = nil\n    init(_ value: String) {{ self.stringValue = value }}\n    init?(stringValue: String) {{ self.stringValue = stringValue }}\n    init?(intValue: Int) {{ return nil }}\n}}\n"
    )
}

fn client_runtime() -> String {
    let runtime = format!(
        "{NOTICE}\nimport Foundation\n#if canImport(FoundationNetworking)\nimport FoundationNetworking\n#endif\n\npublic struct KajiClientOptions: Sendable {{\n    public var baseURL: URL\n    public var headers: [String: String]\n    public var timeout: TimeInterval\n\n    public init(baseURL: URL, headers: [String: String] = [:], timeout: TimeInterval = 30) {{\n        self.baseURL = baseURL\n        self.headers = headers\n        self.timeout = timeout\n    }}\n}}\n\npublic enum KajiAPIError: Error, Sendable {{\n    case invalidURL(String)\n    case invalidResponse\n    case status(code: Int, body: Data)\n}}\n\n/// Receives lifecycle notifications without requiring a logging framework.\npublic protocol KajiClientHook: Sendable {{\n    func willSend(_ request: URLRequest)\n    func didReceive(_ response: HTTPURLResponse, body: Data)\n}}\n\npublic final class KajiClient: @unchecked Sendable {{\n    private let options: KajiClientOptions\n    private let session: URLSession\n    private let hooks: [any KajiClientHook]\n    private let encoder = JSONEncoder()\n    private let decoder = JSONDecoder()\n\n    public init(options: KajiClientOptions, session: URLSession = .shared, hooks: [any KajiClientHook] = []) {{\n        self.options = options\n        self.session = session\n        self.hooks = hooks\n    }}\n\n    internal func makeRequest(method: String, path: String, query: [URLQueryItem] = []) throws -> URLRequest {{\n        guard var components = URLComponents(url: options.baseURL, resolvingAgainstBaseURL: false), let operationPath = URLComponents(string: path.replacingOccurrences(of: \"?\", with: \"%3F\").replacingOccurrences(of: \"#\", with: \"%23\"))?.percentEncodedPath else {{\n            throw KajiAPIError.invalidURL(path)\n        }}\n        let basePath = components.percentEncodedPath.trimmingCharacters(in: CharacterSet(charactersIn: \"/\"))\n        components.percentEncodedPath = (basePath.isEmpty ? \"\" : \"/\" + basePath) + \"/\" + operationPath.trimmingCharacters(in: CharacterSet(charactersIn: \"/\"))\n        components.queryItems = query.isEmpty ? nil : query\n        guard let url = components.url else {{ throw KajiAPIError.invalidURL(path) }}\n        var request = URLRequest(url: url, timeoutInterval: options.timeout)\n        request.httpMethod = method\n        request.setValue(\"application/json\", forHTTPHeaderField: \"Accept\")\n        for (name, value) in options.headers {{ request.setValue(value, forHTTPHeaderField: name) }}\n        return request\n    }}\n\n    internal func send<T: Decodable>(_ request: URLRequest, as type: T.Type) async throws -> T {{\n        hooks.forEach {{ $0.willSend(request) }}\n        let (data, response) = try await session.data(for: request)\n        guard let http = response as? HTTPURLResponse else {{ throw KajiAPIError.invalidResponse }}\n        hooks.forEach {{ $0.didReceive(http, body: data) }}\n        guard (200..<300).contains(http.statusCode) else {{ throw KajiAPIError.status(code: http.statusCode, body: data) }}\n        return try decoder.decode(T.self, from: data)\n    }}\n\n    internal func sendVoid(_ request: URLRequest) async throws {{\n        hooks.forEach {{ $0.willSend(request) }}\n        let (data, response) = try await session.data(for: request)\n        guard let http = response as? HTTPURLResponse else {{ throw KajiAPIError.invalidResponse }}\n        hooks.forEach {{ $0.didReceive(http, body: data) }}\n        guard (200..<300).contains(http.statusCode) else {{ throw KajiAPIError.status(code: http.statusCode, body: data) }}\n    }}\n\n    internal func encode<T: Encodable>(_ body: T) throws -> Data {{ try encoder.encode(body) }}\n}}\n\nextension String {{\n    var kajiPathComponent: String {{ addingPercentEncoding(withAllowedCharacters: CharacterSet(charactersIn: \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~\")) ?? self }}\n}}\n"
    );
    runtime.replace("public final class KajiClient: @unchecked Sendable {", r#"
/// Replace execution or compose middleware around the Foundation transport.
public protocol KajiTransport: Sendable {
    func execute(_ request: URLRequest) async throws -> (Data, URLResponse)
}
public struct KajiURLSessionTransport: KajiTransport {
    private let session: URLSession
    public init(session: URLSession = .shared) { self.session = session }
    public func execute(_ request: URLRequest) async throws -> (Data, URLResponse) {
        try await session.data(for: request)
    }
}
public typealias KajiNext = @Sendable (URLRequest) async throws -> (Data, URLResponse)
public typealias KajiMiddleware = @Sendable (URLRequest, KajiNext) async throws -> (Data, URLResponse)
/// Outer middleware runs first on requests and last on responses.
public struct KajiMiddlewareTransport: KajiTransport {
    private let inner: any KajiTransport
    private let middleware: KajiMiddleware
    public init(inner: any KajiTransport, middleware: @escaping KajiMiddleware) {
        self.inner = inner; self.middleware = middleware
    }
    public func execute(_ request: URLRequest) async throws -> (Data, URLResponse) {
        try await middleware(request, { request in try await inner.execute(request) })
    }
}
public final class KajiClient: @unchecked Sendable {"#)
    .replace("    private let hooks: [any KajiClientHook]", "    private let transport: any KajiTransport\n    private let hooks: [any KajiClientHook]")
    .replace("hooks: [any KajiClientHook] = [])", "hooks: [any KajiClientHook] = [], transport: (any KajiTransport)? = nil)")
    .replace("        self.options = options\n        self.session = session", "        self.options = options\n        self.session = session\n        self.transport = transport ?? KajiURLSessionTransport(session: session)")
    .replace("try await session.data(for: request)", "try await transport.execute(request)")
    // Preserve the default adapter's direct Foundation execution.
    .replace("        try await transport.execute(request)\n    }\n}\npublic typealias", "        try await session.data(for: request)\n    }\n}\npublic typealias")
}

fn render_model_for_api(api: &Api, schema: &Schema) -> String {
    fn recursive(
        api: &Api,
        value: &SchemaValue,
        target: &str,
        seen: &mut std::collections::BTreeSet<String>,
    ) -> bool {
        match &value.kind {
            SchemaKind::Reference { reference } => {
                let name = reference.rsplit('/').next().unwrap_or(reference);
                if name == target {
                    return true;
                }
                seen.insert(name.to_owned())
                    && api
                        .schemas
                        .iter()
                        .find(|schema| schema.name == name)
                        .is_some_and(|schema| recursive(api, &schema.value, target, seen))
            }
            SchemaKind::Object { fields, .. } => fields
                .iter()
                .any(|field| recursive(api, &field.value, target, seen)),
            // Arrays and dictionaries already provide value-type indirection in Swift.
            _ => false,
        }
    }
    if let SchemaKind::Object {
        fields,
        additional_properties,
    } = &schema.value.kind
    {
        if recursive(api, &schema.value, &schema.name, &mut Default::default()) {
            return render_object_kind(
                &type_name(&schema.name),
                fields,
                additional_properties,
                true,
            );
        }
    }
    render_model(schema)
}

fn render_model(schema: &Schema) -> String {
    let name = type_name(&schema.name);
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => render_object(&name, fields, additional_properties),
        SchemaKind::String if !schema.value.enum_values.is_empty() => {
            render_enum(&name, &schema.value.enum_values)
        }
        _ => format!(
            "{NOTICE}\nimport Foundation\n\npublic typealias {name} = {}\n",
            swift_type(&schema.value, false)
        ),
    }
}

fn render_object(name: &str, fields: &[Field], additional: &AdditionalProperties) -> String {
    render_object_kind(name, fields, additional, false)
}

fn render_object_kind(
    name: &str,
    fields: &[Field],
    additional: &AdditionalProperties,
    recursive: bool,
) -> String {
    let open = !matches!(additional, AdditionalProperties::Forbidden);
    let mut extra = "additionalProperties".to_owned();
    while fields
        .iter()
        .any(|field| identifier(&field.name).trim_matches('`') == extra)
    {
        extra.push('_');
    }
    let mut present = "_kajiPresentFields".to_owned();
    while fields
        .iter()
        .any(|field| identifier(&field.name).trim_matches('`') == present)
        || present == extra
    {
        present.push('_');
    }
    let extra_type = match additional {
        AdditionalProperties::Schema { value } => swift_type(value, false),
        _ => "JSONValue".into(),
    };
    let kind = if recursive { "final class" } else { "struct" };
    let property = if recursive { "let" } else { "var" };
    let presence = if recursive {
        format!("private let {present}: Set<String>")
    } else {
        format!("private var {present}: Set<String> = []")
    };
    let mut output = format!(
        "{NOTICE}\nimport Foundation\n\npublic {kind} {name}: Codable, Sendable {{\n    {presence}\n"
    );
    for field in fields {
        let _ = writeln!(
            output,
            "    public {property} {}: {}",
            identifier(&field.name),
            swift_type(&field.value, !field.required)
        );
    }
    if open {
        let _ = writeln!(
            output,
            "    public {property} {extra}: [String: {extra_type}]"
        );
    }
    let mut args = fields
        .iter()
        .map(|field| {
            format!(
                "{}: {}{}",
                identifier(&field.name),
                swift_type(&field.value, !field.required),
                if field.required { "" } else { " = nil" }
            )
        })
        .collect::<Vec<_>>();
    if open {
        args.push(format!("{extra}: [String: {extra_type}] = [:]"));
    }
    let _ = writeln!(output, "\n    public init({}) {{", args.join(", "));
    if recursive {
        let _ = writeln!(output, "        self.{present} = []");
    }
    for field in fields {
        let generated = identifier(&field.name);
        let _ = writeln!(output, "        self.{generated} = {generated}");
    }
    if open {
        let _ = writeln!(output, "        self.{extra} = {extra}");
    }
    output.push_str("    }\n\n    public init(from decoder: Decoder) throws {\n        let container = try decoder.container(keyedBy: KajiCodingKey.self)\n");
    let _ = writeln!(
        output,
        "        self.{present} = Set(container.allKeys.map(\\.stringValue))"
    );
    for field in fields {
        let generated = identifier(&field.name);
        let key = format!("KajiCodingKey({:?})", field.name);
        let ty = swift_type(&field.value, !field.required);
        let base = ty.strip_suffix('?').unwrap_or(&ty);
        if field.required && ty.ends_with('?') {
            let _ = writeln!(
                output,
                "        guard container.contains({key}) else {{ throw DecodingError.keyNotFound({key}, .init(codingPath: decoder.codingPath, debugDescription: \"Missing required property\")) }}"
            );
        }
        let decode = if ty.ends_with('?') {
            "decodeIfPresent"
        } else {
            "decode"
        };
        let _ = writeln!(
            output,
            "        self.{generated} = try container.{decode}({base}.self, forKey: {key})"
        );
    }
    let known = fields
        .iter()
        .map(|field| format!("{:?}", field.name))
        .collect::<Vec<_>>()
        .join(", ");
    if open {
        let _ = writeln!(
            output,
            "        var kajiExtra: [String: {extra_type}] = [:]\n        let known: Set<String> = [{known}]\n        for key in container.allKeys where !known.contains(key.stringValue) {{\n            kajiExtra.updateValue(try container.decode({extra_type}.self, forKey: key), forKey: key.stringValue)\n        }}\n        self.{extra} = kajiExtra"
        );
    }
    output.push_str("    }\n\n    public func encode(to encoder: Encoder) throws {\n        var container = encoder.container(keyedBy: KajiCodingKey.self)\n");
    if open {
        let _ = writeln!(
            output,
            "        let known: Set<String> = [{known}]\n        for (key, value) in {extra} where !known.contains(key) {{ try container.encode(value, forKey: KajiCodingKey(key)) }}"
        );
    }
    for field in fields {
        let generated = identifier(&field.name);
        let key = format!("KajiCodingKey({:?})", field.name);
        let ty = swift_type(&field.value, !field.required);
        if ty.ends_with('?') {
            let condition = if field.required {
                "true".to_owned()
            } else {
                format!("{present}.contains({:?})", field.name)
            };
            let _ = writeln!(
                output,
                "        if let value = {generated} {{ try container.encode(value, forKey: {key}) }} else if {condition} {{ try container.encodeNil(forKey: {key}) }}"
            );
        } else {
            let _ = writeln!(
                output,
                "        try container.encode({generated}, forKey: {key})"
            );
        }
    }
    output.push_str("    }\n}\n");
    output
}

fn render_enum(name: &str, values: &[Value]) -> String {
    let mut output = format!(
        "{NOTICE}\nimport Foundation\n\npublic enum {name}: String, Codable, Sendable {{\n"
    );
    for (index, value) in values.iter().enumerate() {
        let raw = value.as_str().unwrap_or_default();
        let _ = writeln!(output, "    case {} = {:?}", enum_case(raw, index), raw);
    }
    output.push_str("}\n");
    output
}

fn render_operations(api: &Api) -> String {
    let mut output = format!("{NOTICE}\nimport Foundation\n\npublic extension KajiClient {{\n");
    for operation in &api.operations {
        output.push_str(&render_operation(operation, "    "));
    }
    output.push_str("}\n");
    output
}

fn render_operation(operation: &Operation, indent: &str) -> String {
    let name = function_name(&operation.id);
    let parameters = operation_parameters(operation);
    let response = operation
        .success_schema()
        .map(|schema| swift_type(schema, false))
        .unwrap_or_else(|| "Void".to_owned());
    let mut output = String::new();
    let _ = write!(output, "{indent}func {name}(");
    for (index, parameter) in parameters.iter().enumerate() {
        if index > 0 {
            output.push_str(", ");
        }
        output.push_str(&parameter.signature);
    }
    let _ = writeln!(output, ") async throws -> {response} {{");
    let mut path = operation.path.clone();
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "path")
    {
        let value = identifier(&parameter.name);
        let _ = writeln!(
            output,
            "{indent}    let {value}Path = String(describing: {value}).kajiPathComponent"
        );
        path = path.replace(
            &format!("{{{}}}", parameter.name),
            &format!("\\({value}Path)"),
        );
    }
    let request_binding = if operation.request_body.is_some()
        || operation
            .parameters
            .iter()
            .any(|parameter| parameter.location == "header")
    {
        "var"
    } else {
        "let"
    };
    let _ = writeln!(
        output,
        "{indent}    {request_binding} request = try makeRequest(method: {:?}, path: \"{}\", query: ([",
        operation.method.as_str(),
        swift_path_literal(&path)
    );
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "query")
    {
        let value = identifier(&parameter.name);
        let array = parameter
            .schema
            .as_ref()
            .is_some_and(|schema| matches!(schema.kind, SchemaKind::Array { .. }));
        let expression = if array {
            let values = if parameter.required {
                value.clone()
            } else {
                format!("({value} ?? [])")
            };
            if parameter
                .annotations
                .get("explode")
                .and_then(serde_json::Value::as_bool)
                == Some(false)
            {
                if parameter.required {
                    format!(
                        "[URLQueryItem(name: {:?}, value: {values}.map {{ String(describing: $0) }}.joined(separator: \",\"))]",
                        parameter.name
                    )
                } else {
                    format!(
                        "{value}.map {{ [URLQueryItem(name: {:?}, value: $0.map {{ String(describing: $0) }}.joined(separator: \",\"))] }} ?? []",
                        parameter.name
                    )
                }
            } else {
                format!(
                    "{values}.map {{ URLQueryItem(name: {:?}, value: String(describing: $0)) }}",
                    parameter.name
                )
            }
        } else if parameter.required {
            format!(
                "[URLQueryItem(name: {:?}, value: String(describing: {value}))]",
                parameter.name
            )
        } else {
            format!(
                "{value}.map {{ [URLQueryItem(name: {:?}, value: String(describing: $0))] }} ?? []",
                parameter.name
            )
        };
        let _ = writeln!(output, "{indent}        {expression},");
    }
    output.push_str(&format!(
        "{indent}    ] as [[URLQueryItem]]).flatMap {{ $0 }})\n"
    ));
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "header")
    {
        let value = identifier(&parameter.name);
        if parameter.required {
            let _ = writeln!(
                output,
                "{indent}    request.setValue(String(describing: {value}), forHTTPHeaderField: {:?})",
                parameter.name
            );
        } else {
            let _ = writeln!(
                output,
                "{indent}    if let {value} {{ request.setValue(String(describing: {value}), forHTTPHeaderField: {:?}) }}",
                parameter.name
            );
        }
    }
    if let Some(policy) =
        kaji_core::idempotency::resolved(operation).filter(|policy| policy.auto_generate)
    {
        let value = identifier(&policy.parameter_name);
        let _ = writeln!(
            output,
            "{indent}    if {value} == nil {{ request.setValue(UUID().uuidString.lowercased(), forHTTPHeaderField: {:?}) }}",
            policy.header
        );
    }
    if let Some(body) = &operation.request_body {
        let content_type = body
            .media_types
            .first()
            .map(|media| media.content_type.as_str())
            .unwrap_or("application/json");
        let _ = writeln!(
            output,
            "{indent}    request.setValue({content_type:?}, forHTTPHeaderField: \"Content-Type\")"
        );
        if body.required {
            let _ = writeln!(output, "{indent}    request.httpBody = try encode(body)");
        } else {
            let _ = writeln!(
                output,
                "{indent}    if let body {{ request.httpBody = try encode(body) }}"
            );
        }
    }
    if response == "Void" {
        let _ = writeln!(output, "{indent}    try await sendVoid(request)");
    } else {
        let _ = writeln!(
            output,
            "{indent}    return try await send(request, as: {response}.self)"
        );
    }
    let _ = writeln!(output, "{indent}}}\n");
    output
}

struct ParameterRender {
    signature: String,
}

fn operation_parameters(operation: &Operation) -> Vec<ParameterRender> {
    let mut values = operation
        .parameters
        .iter()
        .filter(|parameter| matches!(parameter.location.as_str(), "path" | "query" | "header"))
        .map(|parameter| ParameterRender {
            signature: format!(
                "{}: {}{}",
                identifier(&parameter.name),
                parameter.schema.as_ref().map_or_else(
                    || "JSONValue".to_owned(),
                    |schema| swift_type(schema, !parameter.required)
                ),
                if parameter.required { "" } else { " = nil" }
            ),
        })
        .collect::<Vec<_>>();
    if let Some(body) = &operation.request_body {
        let ty = body
            .media_types
            .iter()
            .find(|media| {
                media.content_type == "application/json" || media.content_type.ends_with("+json")
            })
            .or_else(|| body.media_types.first())
            .and_then(|media| media.schema.as_ref())
            .map_or_else(
                || "JSONValue".to_owned(),
                |schema| swift_type(schema, !body.required),
            );
        values.push(ParameterRender {
            signature: format!("body: {ty}{}", if body.required { "" } else { " = nil" }),
        });
    }
    values
}

fn operation_groups(api: &Api) -> BTreeMap<String, Vec<&Operation>> {
    let mut groups = BTreeMap::new();
    for operation in &api.operations {
        let segment = operation
            .path
            .split('/')
            .find(|part| !part.is_empty() && !part.starts_with('{'))
            .unwrap_or("api");
        groups
            .entry(type_name(segment))
            .or_insert_with(Vec::new)
            .push(operation);
    }
    groups
}

fn render_resource(api: &Api, resource: &str, operations: &[&Operation]) -> String {
    let property = identifier(&lower_camel(resource));
    let mut output = format!(
        "{NOTICE}\nimport Foundation\n\npublic extension KajiClient {{\n    var {property}: {resource}Resource {{ {resource}Resource(client: self) }}\n}}\n\npublic struct {resource}Resource: Sendable {{\n    private let client: KajiClient\n    internal init(client: KajiClient) {{ self.client = client }}\n"
    );
    for operation in operations {
        let name = function_name(&operation.id);
        let parameters = operation_parameters(operation);
        let response = operation
            .success_schema()
            .map(|schema| swift_type(schema, false))
            .unwrap_or_else(|| "Void".to_owned());
        let _ = write!(output, "\n    public func {name}(");
        for (index, parameter) in parameters.iter().enumerate() {
            if index > 0 {
                output.push_str(", ");
            }
            output.push_str(&parameter.signature);
        }
        let _ = writeln!(output, ") async throws -> {response} {{");
        let call_args = parameters
            .iter()
            .map(|parameter| {
                let label = parameter.signature.split(':').next().unwrap_or_default();
                format!("{label}: {label}")
            })
            .collect::<Vec<_>>()
            .join(", ");
        if response == "Void" {
            let _ = writeln!(output, "        try await client.{name}({call_args})");
        } else {
            let _ = writeln!(
                output,
                "        return try await client.{name}({call_args})"
            );
        }
        output.push_str("    }\n");
    }
    let mut resource_api = api.clone();
    resource_api
        .operations
        .retain(|operation| operations.iter().any(|item| item.id == operation.id));
    if let Ok(pages) = pagination::render(&resource_api) {
        output.push_str(
            &pages
                .replace("    func ", "    public func ")
                .replace("self.", "client.")
                .replace("{ current in", "{ [client] current in"),
        );
    }
    output.push_str("}\n");
    output
}

fn swift_type(schema: &SchemaValue, optional: bool) -> String {
    let mut ty = match &schema.kind {
        SchemaKind::Any
        | SchemaKind::Null
        | SchemaKind::Not { .. }
        | SchemaKind::OneOf { .. }
        | SchemaKind::AnyOf { .. }
        | SchemaKind::AllOf { .. } => "JSONValue".to_owned(),
        SchemaKind::Boolean => "Bool".to_owned(),
        SchemaKind::Integer => "Int".to_owned(),
        SchemaKind::Number => "Double".to_owned(),
        SchemaKind::String => "String".to_owned(),
        SchemaKind::Array { items } => format!("[{}]", swift_type(items, false)),
        SchemaKind::Object { .. } => "JSONValue".to_owned(),
        SchemaKind::Reference { reference } => {
            type_name(reference.rsplit('/').next().unwrap_or(reference))
        }
    };
    if optional || schema.nullable || schema.optional || schema.nullish {
        ty.push('?');
    }
    ty
}

fn type_name(value: &str) -> String {
    let result = value
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars.next().map_or_else(String::new, |first| {
                first.to_ascii_uppercase().to_string() + chars.as_str()
            })
        })
        .collect::<String>();
    let result = if result.is_empty() {
        "KajiAPI".to_owned()
    } else {
        result
    };
    if result
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        format!("Kaji{result}")
    } else {
        result
    }
}

fn lower_camel(value: &str) -> String {
    let upper = type_name(value);
    let mut chars = upper.chars();
    chars.next().map_or_else(
        || "api".to_owned(),
        |first| first.to_ascii_lowercase().to_string() + chars.as_str(),
    )
}

fn kebab_case(value: &str) -> String {
    let value = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>();
    let value = value
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    if value.is_empty() {
        "kaji".to_owned()
    } else {
        value
    }
}

fn function_name(value: &str) -> String {
    identifier(&lower_camel(value))
}

fn identifier(value: &str) -> String {
    let mut value = lower_camel(value);
    if value.is_empty() {
        value = "value".to_owned();
    }
    if value
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        value.insert(0, '_');
    }
    if matches!(
        value.as_str(),
        "as" | "associatedtype"
            | "break"
            | "case"
            | "catch"
            | "class"
            | "continue"
            | "default"
            | "defer"
            | "deinit"
            | "do"
            | "else"
            | "enum"
            | "extension"
            | "fallthrough"
            | "false"
            | "fileprivate"
            | "for"
            | "func"
            | "guard"
            | "if"
            | "import"
            | "in"
            | "init"
            | "inout"
            | "internal"
            | "is"
            | "let"
            | "nil"
            | "open"
            | "operator"
            | "private"
            | "protocol"
            | "public"
            | "repeat"
            | "return"
            | "self"
            | "static"
            | "struct"
            | "subscript"
            | "super"
            | "switch"
            | "throw"
            | "throws"
            | "true"
            | "try"
            | "typealias"
            | "var"
            | "where"
            | "while"
    ) {
        format!("`{value}`")
    } else {
        value
    }
}

fn enum_case(value: &str, index: usize) -> String {
    let name = identifier(value).trim_matches('`').to_owned();
    if name.is_empty() || name == "value" {
        format!("value{index}")
    } else {
        name
    }
}

/// Escapes only characters which terminate a Swift string. In particular, it
/// preserves `\\(expression)` interpolation inserted for OpenAPI path values.
fn swift_path_literal(value: &str) -> String {
    value
        .replace('"', "\\\"")
        .replace('\r', "\\r")
        .replace('\n', "\\n")
}

